module.exports = "<!-- Elements of a list template -->\n<ng-template\n  #elementsTemplate\n  let-elements=\"elements\"\n  let-parentElement=\"parentElement\"\n  let-level=\"level\"\n>\n  @for (element of elements; track $index) {\n    <li class=\"bmb_sidebar-list-item\" (click)=\"closeSidebar(element)\">\n      <bmb-check-external-link-button\n        class=\"bmb_sidebar-element\"\n        [idElement]=\"'element' + element.id!\"\n        [link]=\"getLink(element)\"\n        [target]=\"element.target\"\n        (buttonClick)=\"checkForCustomEvent(element, parentElement)\"\n      >\n        <section class=\"bmb_sidebar-item\">\n          @if (!!element.icon) {\n            <bmb-icon\n              class=\"bmb_sidebar-item-icon\"\n              [icon]=\"element.icon\"\n              [alt]=\"element.title\"\n              [size]=\"24\"\n            />\n          }\n\n          <span class=\"bmb_sidebar-item-text\">\n            {{ element!.title }}\n          </span>\n\n          @if (level === 1 && !!element.children) {\n            <bmb-icon\n              class=\"bmb_sidebar-item-arrow\"\n              [icon]=\"position() === 'right' ? 'chevron_left' : 'chevron_right'\"\n              [size]=\"24\"\n            />\n          }\n        </section>\n      </bmb-check-external-link-button>\n\n      <!-- Children -->\n      @if (!!element.children) {\n        <section\n          class=\"bmb_sidebar-children\"\n          [ngClass]=\"{\n            open: element.isOpen,\n            'bmb_sidebar-children-right': position() === 'right'\n          }\"\n        >\n          <ng-container\n            *ngTemplateOutlet=\"\n              sidebarTemplate;\n              context: {\n                elements: element.children?.slice(0, 6),\n                parentElement: element,\n                level: level + 1,\n                selectedElement: element\n              }\n            \"\n          />\n        </section>\n      }\n    </li>\n  }\n</ng-template>\n\n<!-- Content template -->\n<ng-template\n  #sidebarTemplate\n  let-elements=\"elements\"\n  let-level=\"level\"\n  let-selectedElement=\"selectedElement\"\n  let-parentElement=\"parentElement\"\n  let-showHeader=\"showHeader\"\n>\n  <section class=\"bmb_sidebar-menu\">\n    <section class=\"bmb_sidebar-header\">\n      <section class=\"bmb_sidebar-header-wrapper\">\n        @if (level >= 2) {\n          <bmb-action-icon\n            class=\"bmb_sidebar-header-back\"\n            [idElement]=\"'button'.concat(selectedElement?.id?.toString())\"\n            icon=\"chevron_left\"\n            [iconSize]=\"24\"\n            (buttonClick)=\"toggleChildren(selectedElement)\"\n            [alt]=\"'sidebar.back' | translate\"\n          />\n        }\n\n        <span class=\"bmb_sidebar-header-title\">\n          {{ selectedElement?.title }}\n        </span>\n\n        <bmb-action-icon\n          class=\"bmb_sidebar-header-close\"\n          idElement=\"sidebar_close\"\n          icon=\"close\"\n          [iconSize]=\"24\"\n          [isAccentColor]=\"false\"\n          (buttonClick)=\"closeSidebar(selectedElement)\"\n          [alt]=\"'sidebar.close' | translate\"\n        />\n      </section>\n      <bmb-divider />\n    </section>\n\n    <!-- List -->\n    <ul class=\"bmb_sidebar-list\">\n      @if (level === 1) {\n        @for (group of elements; track $index) {\n          @if ($index > 0) {\n            <bmb-divider />\n          }\n\n          <ng-container\n            *ngTemplateOutlet=\"\n              elementsTemplate;\n              context: {\n                elements: group,\n                parentElement,\n                level\n              }\n            \"\n          />\n        }\n      } @else {\n        <ng-container\n          *ngTemplateOutlet=\"\n            elementsTemplate;\n            context: {\n              elements,\n              parentElement,\n              level\n            }\n          \"\n        />\n      }\n    </ul>\n  </section>\n</ng-template>\n\n@if (!error) {\n  <bmb-action-icon\n    class=\"bmb_sidebar-button\"\n    idElement=\"sidebar_main\"\n    icon=\"chevron_right\"\n    [iconSize]=\"32\"\n    toggleIconActive=\"chevron_left\"\n    [isAccentColor]=\"false\"\n    [(isToggleActive)]=\"isOpen\"\n    (buttonClick)=\"handleClose()\"\n    [alt]=\"'sidebar.open_menu'\"\n  />\n  <nav\n    #sideNav\n    class=\"bmb_sidebar\"\n    [ngClass]=\"{\n      open: isOpen,\n      'bmb_sidebar-right': position() === 'right'\n    }\"\n    aria-label=\"Sidebar Navigation\"\n  >\n    <ng-container\n      *ngTemplateOutlet=\"\n        sidebarTemplate;\n        context: {\n          elements: elements().slice(0, 2),\n          level: 1,\n          selectedElement: { title: componentTitle(), id: 1 }\n        }\n      \"\n    />\n  </nav>\n} @else {\n  <p class=\"bmb_sidebar-error\">\n    Error: The sidebar component has exceeded the maximum allowed elements.\n  </p>\n}\n";

